export type AuthMethod = { "kind": "device", device_url: string, token_url: string, client_id_env: string, scopes: string, } | { "kind": "broker", registration: string, } | { "kind": "aws_sso" };
export type ConfigField = { key: string, label: string, placeholder: string, required: boolean, 
/**
 * Masked until revealed. Values not marked secret are shown as they are.
 */
secret: boolean, 
/**
 * Environment variable used when exporting this field, if any.
 */
env: string, };
export type OperationKind = "identity" | "list_resources" | "list_credentials" | "read_credential" | "create_credential" | "validate_credential" | "deactivate_credential" | "revoke_credential" | "write_secret" | "guide";
